def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)


def build_press(name: str, compression_ratio: float):
    """Return a kvpress press, or None for the uncompressed baseline.

    Each method lives in its own file, scripts/presses/<name>.py, with a build(compression_ratio)
    function (see presses/__init__.py). Branches for different methods then never edit the same lines.
    """
    if name == "none":
        return None
    try:
        module = importlib.import_module(f"presses.{name}")
    except ModuleNotFoundError as e:
        if e.name not in ("presses", f"presses.{name}"):
            raise  # the press file exists but one of its own imports is missing
        raise ValueError(f"Unknown press '{name}': add scripts/presses/{name}.py") from None
    return module.build(compression_ratio)


def kv_bytes_per_token(config, dtype_bytes: int = 2) -> int:
    """Theoretical uncompressed KV-cache size per token: layers x kv_heads x head_dim x 2 (K and V) x bytes."""
    head_dim = getattr(config, "head_dim", None) or config.hidden_size // config.num_attention_heads
    return config.num_hidden_layers * config.num_key_value_heads * head_dim * 2 * dtype_bytes


def cache_bytes(cache) -> int:
    """Bytes actually held by a DynamicCache (shrinks once a press evicts tokens).
    Quantized caches store their data elsewhere; extend this when the team adds one."""
    total = 0
    for layer in cache.layers:
        for t in (layer.keys, layer.values):
            if t is not None:
                total += t.numel() * t.element_size()
    return total


class GpuEnergy:
    """Cumulative GPU energy from NVML (Volta and newer), in joules. Returns None where unsupported."""

    def __init__(self, index: int = 0):
        try:
            import pynvml

            pynvml.nvmlInit()
            self._nvml = pynvml
            self._handle = pynvml.nvmlDeviceGetHandleByIndex(index)
            self.read()
        except Exception:
            self._nvml = None

    def read(self):
        if self._nvml is None:
            return None
        return self._nvml.nvmlDeviceGetTotalEnergyConsumption(self._handle) / 1e3  # mJ -> J


class ForwardTimer:
    """Times every forward call of a module, synchronising the GPU around each one.

    Hooked on the decoder (model.model), which runs once for the context prefill (press included),
    once for the question, then once per generated token.
    """

    def __init__(self, module: torch.nn.Module):
        self.calls = []  # (input_tokens, seconds)
        self._t0 = None
        module.register_forward_pre_hook(self._pre, with_kwargs=True)
        module.register_forward_hook(self._post, with_kwargs=True)

    def reset(self):
        self.calls = []

    def _pre(self, module, args, kwargs):
        torch.cuda.synchronize()
        ids = kwargs.get("input_ids", args[0] if args else None)
        self._n = ids.shape[1] if ids is not None else 0
        self._t0 = time.perf_counter()

    def _post(self, module, args, kwargs, output):
        torch.cuda.synchronize()
        self.calls.append((self._n, time.perf_counter() - self._t0))


def _pkg_version(name: str) -> str:
    try:
        return importlib.metadata.version(name)
    except importlib.metadata.PackageNotFoundError:
        return "not installed"


def env_info() -> dict:
    """Everything needed to report the setup in the paper (GPU, driver, package versions, code commit)."""
    try:
        commit = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()
    except Exception:
        commit = "unknown"
    try:
        driver = subprocess.check_output(
            ["nvidia-smi", "--query-gpu=driver_version", "--format=csv,noheader"], text=True
        ).strip()
    except Exception:
        driver = "unknown"
    return {
        "gpu": torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu",
        "gpu_count": torch.cuda.device_count(),
        "gpu_memory_gb": round(torch.cuda.get_device_properties(0).total_memory / 1e9, 1)
        if torch.cuda.is_available()
        else 0,
        "driver": driver,
        "cuda": torch.version.cuda,
        "python": platform.python_version(),
        "torch": torch.__version__,
        "transformers": _pkg_version("transformers"),
        "kvpress": _pkg_version("kvpress"),
        "pandas": _pkg_version("pandas"),
        "git_commit": commit,
    }
